/* SRT Smart Voice Studio v3 — script.js (adapted from original JavaScript.txt)
   Compatible with SRT-Smart-Voice-Studio-v3.html: uses v3 state/IDs,
   keeps original tag format <piseth speed=".." pitch="..">..</piseth>
   and backend POST /api/process-multi (FormData: data=parts, autoSpeed). */
"use strict";
// --- Register Service Worker (ដើម្បីដំឡើងជា App / Add to Home Screen បាន) ---
if ('serviceWorker' in navigator) {
  window.addEventListener('load', () => {
    navigator.serviceWorker.register('/service-worker.js')
      .then(reg => console.log('✅ Service Worker បានចុះឈ្មោះជោគជ័យ:', reg.scope))
      .catch(err => console.log('❌ Service Worker ចុះឈ្មោះបរាជ័យ:', err));
  });
}

/* ================================================================
   v3 — Inline Line Editor
   គំរូទិន្នន័យ៖ blocks[] -> { start, end, lines[] }
   lines[]      -> { text, voice, speed, pitch, custom }
   - មួយ "ជួរ" ក្នុង Editor = មួយ line (មាន ♂️/♀️ នៅមុខផ្ទាល់)
   - Block មួយអាចមានច្រើនជួរ (ដូច SRT ដើម) ពេលវេលារក្សានៅ block
   - Export៖ គ្រប់ជួរក្នុង block បញ្ចូលគ្នាវិញក្រោមពេលវេលាតែមួយ
     => ទម្រង់ SRT ដើមមិនបាត់ឡើយ
   ================================================================ */
const MALE = "\u2642", FEMALE = "\u2640"; // ♂ ♀
const VOICES = {
  piseth:  { key:"piseth",  label:"Piseth",  sym:MALE,   name:"ប្រុស", edge:"km-KH-PisethNeural"  },
  sreymom: { key:"sreymom", label:"Sreymom", sym:FEMALE, name:"ស្រី",  edge:"km-KH-SreymomNeural" }
};
let uid = 0, bid = 0;
let blocks = [];            // {id, start, end, lines:[{id,text,voice,speed,pitch,custom}]}
let isSRT = false;
let mode = "raw";           // 'raw' | 'doc'
let speaking = false;
let pendingFocus = null;
let renderLimit = 100;          /* បង្ហាញម្តង 100 ជួរ (ទិន្នន័យនៅគ្រប់ទាំងអស់ រហូតដល់ 500+ ជួរ) */
const RENDER_BATCH = 100;
const openTunes = new Set();
const defaults = { piseth:{speed:1,pitch:0}, sreymom:{speed:1,pitch:0} };
/* --- Compatibility with original script.js: voiceConfigs + Auto Speed + /api/process-multi parts --- */
const voiceConfigs = {
  piseth:  { speed:1.0, pitch:0, voice:"km-KH-PisethNeural",  name:"Piseth"  },
  sreymom: { speed:1.0, pitch:0, voice:"km-KH-SreymomNeural", name:"Sreymom" }
};
let isAutoSpeedActive = false;
function syncVoiceConfigs(){ ["piseth","sreymom"].forEach(k=>{ voiceConfigs[k].speed = defaults[k].speed; voiceConfigs[k].pitch = defaults[k].pitch; }); }
window.voiceConfigs = voiceConfigs;
/* parts format expected by POST /api/process-multi : [{text, voiceName, speed, pitch}] */
function cleanSpeakText(t){
  return String(t || "").replace(/[\u0000-\u001F\u007F\u200B\uFEFF\uFFFD]/g, "").trim();
}
function hasSpeakable(t){ return /[\p{L}\p{N}]/u.test(t); } /* មានអក្សរ ឬលេខ ដែលអានបាន */
function buildParts(){
  /* បង្កើត parts សម្រាប់ /api/process-multi ដោយភ្ជាប់ពេលវេលា SRT (start/end)
     របស់ Block នីមួយៗ — បើ Block មានច្រើនជួរ នឹងចែកចន្លោះពេលតាមសមាមាត្រតួអក្សរ
     ដើម្បីឱ្យ Backend ដាក់សំឡេងចំពេល និងរក្សាចន្លោះស្ងាត់/ភ្លេងរវាង Subtitle នីមួយៗ */
  const parts = [];
  blocks.forEach((b, bi)=>{
    const t = blockTimes(b, bi);
    const speakLines = b.lines.filter(line=>hasSpeakable(cleanSpeakText(line.text)));
    if(!speakLines.length) return;
    const startSec = srtToSec(t.start), endSec = srtToSec(t.end);
    const totalChars = speakLines.reduce((s,l)=> s + (countTextChars(l.text) || 1), 0);
    let cum = 0;
    speakLines.forEach(line=>{
      const e = eff(line);
      const chars = countTextChars(line.text) || 1;
      const subStart = startSec + (endSec - startSec) * (cum / totalChars);
      const subEnd = startSec + (endSec - startSec) * ((cum + chars) / totalChars);
      cum += chars;
      parts.push({
        text: cleanSpeakText(line.text.replace(/\n/g," ")),
        voiceName: line.voice,
        speed: e.speed, pitch: e.pitch,
        block: bi + 1,
        start: secToSRT(subStart), end: secToSRT(subEnd),
        startMs: Math.round(subStart * 1000), endMs: Math.round(subEnd * 1000)
      });
    });
  });
  return parts;
}
window.buildParts = buildParts;
/* Server ពិត — ប្រើ URL ពេញ (ហៅបានទោះបើកទំព័រពី Preview ឬ Domain ផ្សេងក៏ដោយ) */
const API_URL = "https://takumi0002-tts-kh.hf.space/api/process-multi";
window.API_URL = API_URL;

const $ = s => document.querySelector(s);
const rawEl = $("#raw"), docEl = $("#doc"), docBody = $("#doc-body");

function esc(s){ return String(s ?? "").replace(/&/g,"&amp;").replace(/</g,"&lt;").replace(/>/g,"&gt;").replace(/"/g,"&quot;"); }
function fmtSpeed(v){ return (Math.round(v*100)/100).toFixed(2).replace(/0$/,"") + "x"; }
function fmtPitch(v){ return (v>0?"+":"") + v; }
function otherVoice(v){ return v === "piseth" ? "sreymom" : "piseth"; }
function allLines(){ const out=[]; blocks.forEach(b=>b.lines.forEach(l=>out.push({block:b, line:l}))); return out; }
function eff(line){ const d = defaults[line.voice]; return line.custom ? {speed:line.speed, pitch:line.pitch} : {speed:d.speed, pitch:d.pitch}; }
function findLine(id){ for(const b of blocks){ const i = b.lines.findIndex(l=>l.id===id); if(i>-1) return {block:b, line:b.lines[i], index:i}; } return null; }
function newLine(text, voice){ return { id:++uid, text:text||"", voice:voice||"piseth", speed:1, pitch:0, custom:false }; }

/* ---------- strip / detect speaker tag at front of a text line ---------- */
function stripTag(rawLine){
  let t = rawLine.trim(), voice = null;
  let m = t.match(new RegExp("^([\\u2642\\u2640])\\uFE0F?\\s*[-–—:.]?\\s*"));
  if(m){ voice = m[1] === MALE ? "piseth" : "sreymom"; t = t.slice(m[0].length); }
  else if((m = t.match(/^\[(piseth|sreymom|male|female|ប្រុស|ស្រី)\]\s*/i))){ voice = /piseth|male|ប្រុស/i.test(m[1]) ? "piseth" : "sreymom"; t = t.slice(m[0].length); }
  else if((m = t.match(/^(piseth|sreymom)\s*[:：]\s*/i))){ voice = m[1].toLowerCase(); t = t.slice(m[0].length); }
  return { text:t, voice };
}

/* ---------- Parse Raw -> blocks/lines ---------- */
const TIME_RE = /(\d{1,2}:\d{2}:\d{2}[,.]\d{1,3})\s*-->\s*(\d{1,2}:\d{2}:\d{2}[,.]\d{1,3})/;
/* Legacy tags from original script.js: <piseth speed=".." pitch="..">...</piseth> (may span lines) */
function legacyTagForLine(line, state){
  let text = String(line || ""), found = null;
  const closes = /<\/(piseth|sreymom)>/i.test(text);
  text = text.replace(/<(piseth|sreymom)\b[^>]*>/gi, (m, name)=>{
    const sm = m.match(/speed=["']([^"']+)["']/i), pm = m.match(/pitch=["']([^"']+)["']/i);
    state.voice = name.toLowerCase();
    state.speed = sm ? parseFloat(sm[1]) : 1.0;
    state.pitch = pm ? parseInt(pm[1], 10) : 0;
    found = { voice: state.voice, speed: state.speed, pitch: state.pitch };
    return "";
  });
  text = text.replace(/<\/(piseth|sreymom)>/gi, "");
  if(!found && state.voice) found = { voice: state.voice, speed: state.speed, pitch: state.pitch };
  if(closes){ state.voice = null; state.speed = 1; state.pitch = 0; }
  return { text: text.trim(), tag: found };
}
function makeParsedLine(item, lastVoiceRef){
  const p = stripTag(item.text);
  const voice = (item.tag && item.tag.voice) || p.voice || lastVoiceRef.voice;
  if(p.voice) lastVoiceRef.voice = p.voice;
  if(item.tag) lastVoiceRef.voice = item.tag.voice;
  const line = newLine(p.text, voice);
  if(item.tag){ line.speed = item.tag.speed; line.pitch = item.tag.pitch; line.custom = true; line.fromTag = true; }
  return line;
}
/* --- Auto Speed សម្រាប់ SRT៖ អត្ថបទវែង = អានលឿន ដើម្បីឱ្យទាន់រយៈពេល Subtitle ---
   គណនាពី (១) ចំនួនតួអក្សរ និង (២) រយៈពេលរបស់ Block (end - start)
   ឧទាហរណ៍៖ >60 តួ = 1.5x, >45 តួ = 1.4x, >30 តួ = 1.2x, >20 តួ = 1.1x, ខ្លី = 1.0x
   បើអត្ថបទច្រើនធៀបនឹងរយៈពេលខ្លី វានឹងបង្កើនលើសនេះទៀត (អតិបរមា 1.8x) */
const AUTO_BASE_CPS = 14; /* តួអក្សរ/វិនាទី នៅ Speed 1.0x */
function countTextChars(t){ return Array.from(String(t || "").replace(/\s/g, "")).length; }
function lengthBasedSpeed(chars){
  if(chars > 60) return 1.5;
  if(chars > 45) return 1.4;
  if(chars > 30) return 1.2;
  if(chars > 20) return 1.1;
  return 1.0;
}
function suggestedSpeed(chars, durationSec){
  let s = lengthBasedSpeed(chars);
  if(durationSec > 0){
    const needed = (chars / durationSec) / AUTO_BASE_CPS;
    s = Math.max(s, needed);
  }
  return Math.min(1.8, Math.max(1.0, Math.round(s * 20) / 20));
}
function isAutoSpeedSrtOn(){ const el = $("#auto-speed-srt"); return !el || el.checked; }
function applyAutoSpeedToBlocks(list){
  let sped = 0;
  (list || blocks).forEach(b=>{
    if(!b.start || !b.end) return;
    const dur = srtToSec(b.end) - srtToSec(b.start);
    if(dur <= 0) return;
    const total = b.lines.reduce((sum, l)=> sum + countTextChars(l.text), 0);
    if(!total) return;
    b.lines.forEach(l=>{
      if(l.fromTag) return; /* មិនប្តូរ Speed ដែល Tag <piseth speed=".."> បានកំណត់ស្រាប់ */
      const chars = countTextChars(l.text);
      if(!chars) return;
      const allocated = dur * chars / total; /* ចែករយៈពេល Block តាមសមាមាត្រតួអក្សរ */
      const sp = suggestedSpeed(chars, allocated);
      l.speed = sp; l.custom = true; l.autoSpeed = sp > 1.0;
      if(sp > 1.0) sped++;
    });
  });
  return sped;
}
window.applyAutoSpeedToBlocks = applyAutoSpeedToBlocks;
function parseRaw(text){
  const raw = String(text||"").replace(/\r\n/g,"\n").trim();
  blocks = []; openTunes.clear(); renderLimit = RENDER_BATCH;
  if(!raw) return 0;
  isSRT = TIME_RE.test(raw);
  const lastVoiceRef = { voice: "piseth" };
  if(isSRT){
    raw.split(/\n\s*\n/).forEach(chunk=>{
      const rows = chunk.split("\n").map(r=>r.trim()).filter(r=>r!=="");
      if(!rows.length) return;
      let start=null, end=null; const items=[];
      const tagState = { voice:null, speed:1, pitch:0 };
      rows.forEach(r=>{
        const m = r.match(TIME_RE);
        if(m){ start=m[1].replace(".",","); end=m[2].replace(".",","); }
        else if(start===null && /^\d+$/.test(r)){ /* block number — regenerated on export */ }
        else { const lt = legacyTagForLine(r, tagState); if(lt.text) items.push(lt); }
      });
      if(start === null) return;
      const lines = items.map(item => makeParsedLine(item, lastVoiceRef));
      const block = { id:++bid, start, end, lines: lines.length ? lines : [newLine("", lastVoiceRef.voice)] };
      if(isAutoSpeedSrtOn()) applyAutoSpeedToBlocks([block]);
      blocks.push(block);
    });
  } else {
    const tagState = { voice:null, speed:1, pitch:0 };
    raw.split("\n").map(r=>r.trim()).filter(r=>r!=="").forEach(t=>{
      const lt = legacyTagForLine(t, tagState);
      if(!lt.text) return;
      blocks.push({ id:++bid, start:null, end:null, lines:[ makeParsedLine(lt, lastVoiceRef) ] });
    });
  }
  return allLines().length;
}

/* ---------- Build SRT / script / JSON back out ---------- */
function srtToSec(t){ if(!t) return 0; const p = t.replace(",",".").split(":"); return (+p[0])*3600 + (+p[1])*60 + parseFloat(p[2]); }
function secToSRT(sec){ const h=String(Math.floor(sec/3600)).padStart(2,"0"), m=String(Math.floor(sec%3600/60)).padStart(2,"0"), s=String(Math.floor(sec%60)).padStart(2,"0"), ms=String(Math.round((sec%1)*1000)).padStart(3,"0"); return `${h}:${m}:${s},${ms}`; }
function blockTimes(b, i){ return { start: b.start || secToSRT(i*3), end: b.end || secToSRT(i*3+2.5) }; }
function buildSRT(withTags){
  return blocks.map((b,i)=>{
    const t = blockTimes(b,i);
    const body = b.lines.map(l=>{
      const v = VOICES[l.voice];
      return (withTags ? v.sym + "\uFE0F " : "") + l.text.trim();
    }).join("\n");
    return `${i+1}\n${t.start} --> ${t.end}\n${body}`;
  }).join("\n\n") + (blocks.length ? "\n" : "");
}
function buildScript(){
  return allLines().map(({line})=>{
    const v = VOICES[line.voice], e = eff(line);
    const clean = line.text.replace(/\n/g," ").trim();
    return `${v.sym}\uFE0F <${line.voice} speed="${e.speed}" pitch="${e.pitch}">${clean}</${line.voice}>`;
  }).join("\n");
}

function buildSegments(){
  const out = []; let n = 0;
  blocks.forEach((b,bi)=>{
    const t = blockTimes(b,bi);
    b.lines.forEach(line=>{
      const v = VOICES[line.voice], e = eff(line), rp = Math.round((e.speed-1)*100);
      out.push({ index:++n, block:bi+1, start:t.start, end:t.end, voice:v.edge, voiceKey:v.key, gender:v.sym,
        text: line.text.replace(/\n/g," "), speed:e.speed, rate:(rp>=0?"+":"")+rp+"%",
        pitch:(e.pitch>=0?"+":"")+e.pitch+"Hz", pitchRaw:e.pitch, custom:!!line.custom });
    });
  });
  return out;
}

/* ---------- Render the inline editor ---------- */
function render(){
  const has = blocks.length > 0;
  $("#empty-doc").style.display = has ? "none" : "block";
  const totalLines = allLines().length;
  if(pendingFocus){ const fi = allLines().findIndex(({line})=>line.id===pendingFocus); if(fi >= 0) renderLimit = Math.max(renderLimit, fi + RENDER_BATCH); }
  let shownLines = 0;
  docBody.innerHTML = blocks.map((b,bi)=>{
    const t = blockTimes(b, bi);
    const head = (b.start || isSRT) ? `
      <div class="block-head">
        <span class="block-num">${bi+1}</span>
        <input class="time-input" value="${esc(t.start)}" onchange="updateTime(${b.id},'start',this.value)" title="ពេលចាប់ផ្តើម (កែបាន)">
        <span class="arrow">--&gt;</span>
        <input class="time-input" value="${esc(t.end)}" onchange="updateTime(${b.id},'end',this.value)" title="ពេលបញ្ចប់ (កែបាន)">
        <span class="srt-tag">SRT ✓ រក្សាទុក</span>
        <span class="block-tools">
          <button class="btn small" onclick="addLineToBlock(${b.id})" title="បន្ថែមជួរថ្មីក្នុង Block នេះ">＋ ជួរ</button>
          <button class="btn small danger" onclick="deleteBlock(${b.id})" title="លុប Block នេះ">🗑 Block</button>
        </span>
      </div>` : "";
    const rows = b.lines.map(line=>{
      if(shownLines >= renderLimit) return "";
      shownLines++;
      const v = VOICES[line.voice], e = eff(line), male = line.voice === "piseth";
      return `
      <div class="line-row ${male?"male":"female"}" id="row-${line.id}">
        <button class="g-btn ${male?"male":"female"}" onclick="toggleVoice(${line.id})"
          title="ឥឡូវ៖ ${v.label} (${v.name}) — ចុចដើម្បីប្តូរទៅ ${VOICES[otherVoice(line.voice)].label}">
          <span class="sym">${v.sym}\uFE0F</span><span class="who">${v.label}</span>
        </button>
        <textarea class="line-text" id="text-${line.id}" rows="1" placeholder="វាយអត្ថបទជួរនេះ..."
          oninput="updateText(${line.id}, this.value); autoGrow(this)"
          onkeydown="lineKey(event, ${line.id})">${esc(line.text)}</textarea>
        <button class="ps-badge ${line.custom?"custom":""}" id="ps-${line.id}" onclick="toggleTune(${line.id})"
          title="Pitch / Speed របស់ជួរនេះ">⚙️ ${fmtSpeed(e.speed)} / ${fmtPitch(e.pitch)}${line.custom?" ●":""}</button>
        <button class="play-btn" onclick="previewLine(${line.id})" title="ស្តាប់ជួរនេះ">▶️</button>
      </div>
      <div class="tune ${openTunes.has(line.id)?"open":""}" id="tune-${line.id}">
        <div class="tune-grid">
          <div class="slider-line"><label>⚡ Speed — ${v.label} <output id="sp-val-${line.id}">${fmtSpeed(e.speed)}</output></label>
            <input type="range" min="0.5" max="2" step="0.05" value="${e.speed}" oninput="updateSpeed(${line.id}, this.value)"></div>
          <div class="slider-line"><label>🎵 Pitch — ${v.label} <output id="pi-val-${line.id}">${fmtPitch(e.pitch)}</output></label>
            <input type="range" min="-10" max="10" step="1" value="${e.pitch}" oninput="updatePitch(${line.id}, this.value)"></div>
        </div>
        <div class="row" style="margin-top:9px">
          <button class="btn small" onclick="toggleVoice(${line.id})">⇄ ប្តូរ ♂️/♀️</button>
          <button class="btn small" onclick="resetLine(${line.id})">↺ ប្រើ Default របស់ ${v.label}</button>
          <button class="btn small" onclick="duplicateLine(${line.id})">⧉ ចម្លងជួរ</button>
          <button class="btn small" onclick="moveLine(${line.id},-1)">↑ ឡើង</button>
          <button class="btn small" onclick="moveLine(${line.id},1)">↓ ចុះ</button>
          <button class="btn small danger" onclick="removeLine(${line.id})">🗑 លុបជួរ</button>
          <span style="font-size:11px;color:var(--muted)">${line.custom ? "● Custom — មិនប្រើ Default ទេ" : "កំពុងប្រើ Default របស់ " + v.label}</span>
        </div>
      </div>`;
    }).join("");
    return `<div class="block" id="block-${b.id}">${head}${rows}</div>`;
  }).join("") + (totalLines > shownLines ? `
    <div style="text-align:center;padding:16px 10px;border:1.5px dashed var(--border);border-radius:14px;margin-top:8px;background:var(--card2)">
      <p style="margin:0 0 10px;font-size:13px;color:var(--muted)">📄 បង្ហាញ <b>${shownLines}</b> / <b>${totalLines}</b> ជួរ — នៅសល់ ${totalLines - shownLines} ជួរទៀត<br><span style="font-size:11.5px">ទិន្នន័យនៅគ្រប់ ${totalLines} ជួរទាំងអស់ សម្រាប់ Generate និង Export (គ្រាន់តែបង្ហាញជាដុំៗដើម្បីកុំឱ្យទូរស័ព្ទយឺត)</span></p>
      <button class="btn primary" onclick="loadMoreLines()">⬇️ បង្ហាញបន្ថែម ${RENDER_BATCH} ជួរ</button>
      <button class="btn" onclick="showAllLines()">បង្ហាញទាំងអស់ (${totalLines} ជួរ)</button>
    </div>` : "");
