function setLineVoice(id, voice){ const f = findLine(id); if(!f) return; f.line.voice = voice; render(); }
function updateText(id, val){ const f = findLine(id); if(f) f.line.text = val.replace(/\n/g," "); }
function lineKey(ev, id){
  if(ev.key === "Enter"){ ev.preventDefault(); addLineAfter(id); }
  else if(ev.key === "Backspace" && ev.target.value === ""){ ev.preventDefault(); const f = findLine(id); if(f && allLines().length > 1){ const prev = previousLineId(id); removeLine(id, true); if(prev) pendingFocus = prev; render(); } }
}
function previousLineId(id){ const ls = allLines(); const i = ls.findIndex(x=>x.line.id===id); return i>0 ? ls[i-1].line.id : null; }
function toggleTune(id){ openTunes.has(id) ? openTunes.delete(id) : openTunes.add(id); const t = $("#tune-"+id); if(t) t.classList.toggle("open"); }
function refreshBadge(line){ const e = eff(line); const b = $("#ps-"+line.id); if(b){ b.textContent = `⚙️ ${fmtSpeed(e.speed)} / ${fmtPitch(e.pitch)}${line.custom?" ●":""}`; b.classList.toggle("custom", !!line.custom); } }
function updateSpeed(id, val){ const f = findLine(id); if(!f) return; if(!f.line.custom){ f.line.pitch = eff(f.line).pitch; } f.line.speed = parseFloat(val); f.line.custom = true; const o = $("#sp-val-"+id); if(o) o.textContent = fmtSpeed(f.line.speed); refreshBadge(f.line); }
function updatePitch(id, val){ const f = findLine(id); if(!f) return; if(!f.line.custom){ f.line.speed = eff(f.line).speed; } f.line.pitch = parseInt(val,10); f.line.custom = true; const o = $("#pi-val-"+id); if(o) o.textContent = fmtPitch(f.line.pitch); refreshBadge(f.line); }
function resetLine(id){ const f = findLine(id); if(!f) return; f.line.custom = false; render(); }
function removeLine(id, silent){
  const f = findLine(id); if(!f) return;
  f.block.lines = f.block.lines.filter(l=>l.id!==id);
  if(!f.block.lines.length) blocks = blocks.filter(b=>b.id!==f.block.id);
  if(!silent) render();
}
function duplicateLine(id){ const f = findLine(id); if(!f) return; const c = {...f.line, id:++uid}; f.block.lines.splice(f.index+1,0,c); pendingFocus = c.id; render(); }
function addLineAfter(id){
  const f = findLine(id); if(!f) return;
  const nl = newLine("", otherVoice(f.line.voice)); // ជួរថ្មីឆ្លាស់តួឱ្យងាយសន្ទនា
  f.block.lines.splice(f.index+1,0,nl); pendingFocus = nl.id; render();
}
function addLineToBlock(blockId){
  const b = blocks.find(x=>x.id===blockId); if(!b) return;
  const last = b.lines[b.lines.length-1];
  const nl = newLine("", last ? otherVoice(last.voice) : "piseth");
  b.lines.push(nl); pendingFocus = nl.id; render();
}
function newBlock(afterId){
  let start = null, end = null, idx = blocks.length;
  if(isSRT || blocks.some(b=>b.start)){
    const lastEnd = blocks.length ? srtToSec(blockTimes(blocks[blocks.length-1], blocks.length-1).end) : 0;
    start = secToSRT(lastEnd + 0.5); end = secToSRT(lastEnd + 3);
  }
  const b = { id:++bid, start, end, lines:[ newLine("", "piseth") ] };
  if(afterId){ const i = blocks.findIndex(x=>x.id===afterId); blocks.splice(i+1,0,b); idx = i+1; }
  else blocks.push(b);
  pendingFocus = b.lines[0].id; render();
  return b;
}
function deleteBlock(blockId){ blocks = blocks.filter(b=>b.id!==blockId); render(); }
function moveLine(id, dir){
  const f = findLine(id); if(!f) return; const j = f.index + dir;
  if(j < 0 || j >= f.block.lines.length) return;
  [f.block.lines[f.index], f.block.lines[j]] = [f.block.lines[j], f.block.lines[f.index]];
  pendingFocus = id; render();
}
function updateTime(blockId, which, val){
  const b = blocks.find(x=>x.id===blockId); if(!b) return;
  const v = String(val||"").trim().replace(".",",");
  if(/^\d{1,2}:\d{2}:\d{2},\d{1,3}$/.test(v)){ b[which] = v; } render();
}

