/* ---------- Browser preview ---------- */
function speakLine(line){
  return new Promise(resolve=>{
    const u = new SpeechSynthesisUtterance(line.text.replace(/\n/g," "));
    const e = eff(line);
    const vs = speechSynthesis.getVoices();
    const km = vs.find(v=>/km|khmer|cambodia/i.test(v.lang+" "+v.name));
    if(km) u.voice = km; u.lang = km ? km.lang : "km-KH";
    u.rate = Math.min(2, Math.max(0.5, e.speed));
    u.pitch = Math.min(2, Math.max(0, 1 + e.pitch*0.05));
    u.onend = resolve; u.onerror = resolve; speechSynthesis.speak(u);
  });
}
async function previewLine(id){ const f = findLine(id); if(!f || !f.line.text.trim()) return; stopPreview(); const row = $("#row-"+id); if(row) row.classList.add("playing"); await speakLine(f.line); if(row) row.classList.remove("playing"); }
