  for(const {line} of allLines()){
    if(!speaking) break; if(!line.text.trim()) continue;
    const row = $("#row-"+line.id); if(row){ row.classList.add("playing"); row.scrollIntoView({block:"center", behavior:"smooth"}); }
    await speakLine(line); if(row) row.classList.remove("playing");
  }
