async function generateAudio(){
  if(!blocks.length){ setStatus("⚠️ មិនទាន់មានអត្ថបទក្នុង Editor ទេ សូមបំបែកអត្ថបទជាមុន", "err"); return; }
  const totalTextLines = allLines().filter(({line})=>line.text.trim()).length;
  const parts = buildParts();
  const skippedLines = totalTextLines - parts.length;
  if(!parts.length){ setStatus("⚠️ គ្រប់ជួរគ្មានអក្សរដែលអានបានទេ (មានតែសញ្ញា/វណ្ណយុត្តិ) — សូមពិនិត្យអត្ថបទម្តងទៀត", "err"); return; }
  const btn = $("#generate-btn"), loader = $("#loader");
  btn.disabled = true; btn.innerHTML = '<span class="spin"></span> កំពុងផលិតសំឡេង... សូមរង់ចាំ';
  if(loader) loader.classList.add("show");
  $("#audio-box").classList.remove("show");
  setStatus(`⏳ កំពុងផ្ញើ ${parts.length} parts ទៅ Server (Edge TTS)...${skippedLines > 0 ? ` (បានរំលង ${skippedLines} ជួរដែលគ្មានអក្សរអានបាន)` : ""}`, "busy");
  const formData = new FormData();
  formData.append('data', JSON.stringify(parts));
  formData.append('autoSpeed', isAutoSpeedActive);
  try{
    const response = await fetch(API_URL, { method: 'POST', body: formData });
    if(!response.ok) throw new Error('មានបញ្ហាក្នុងការផលិតសំឡេង (Server ឆ្លើយ ' + response.status + ')');
    const blob = await response.blob();
    const audioUrl = URL.createObjectURL(blob);
    const audioPlayer = $("#audio-player"), downloadLink = $("#download-link");
    audioPlayer.src = audioUrl; downloadLink.href = audioUrl;
    $("#audio-box").classList.add("show");
    setStatus("✅ ផលិតសំឡេងរួចរាល់! ចុច Play ឬទាញយក MP3 ខាងក្រោម", "ok");
    if(audioPlayer.play) audioPlayer.play().catch(()=>{});
  }catch(error){
    console.error('Error generating audio:', error);
    setStatus("❌ កើតមានកំហុស៖ " + error.message + " — កំពុងចាក់ Browser Preview ជំនួសវិញ", "err");
    playAll();
  }finally{
    btn.disabled = false; btn.textContent = "🎙️ ផលិតសំឡេង (Generate Audio)";
    if(loader) loader.classList.remove("show");
  }
}
